package android.location;public class Location {public boolean mock,accuracyPresent=true;public double lat=35.15,lon=-90.0;public float accuracy=8;public long time=System.currentTimeMillis()-1000,nanos=1;public Location(String p){}public Location(Location p){mock=p.mock;accuracyPresent=p.accuracyPresent;lat=p.lat;lon=p.lon;accuracy=p.accuracy;time=p.time;nanos=p.nanos;}public boolean isFromMockProvider(){return mock;}public boolean hasAccuracy(){return accuracyPresent;}public double getLatitude(){return lat;}public double getLongitude(){return lon;}public float getAccuracy(){return accuracy;}public long getTime(){return time;}public long getElapsedRealtimeNanos(){return nanos;}}
